"""Sparse-attribute handling."""

import os

from ._winapi import (
    SPARSE_ATTRIBUTE,
    is_windows,
    get_handle_for_sparse,
    close_handle,
    set_sparse,
)
from .errors import WSParseError


def sparse_state(path):
    """Return ``True`` when ``path`` currently carries the sparse attribute."""
    path = os.fspath(path)

    if not is_windows():
        raise WSParseError(
            "sparse state query requires Windows/NTFS",
            kind="unsupported",
            path=path,
        )

    try:
        info = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    attributes = getattr(info, "st_file_attributes", 0)
    return bool(attributes & SPARSE_ATTRIBUTE)


def sparse_flag(path, enabled=True):
    """Turn the sparse attribute of ``path`` on or off.

    ``enabled`` defaults to ``True``.  Returns the state the file ends up in.

    Note: On NTFS, setting the sparse flag on an already-dense file does NOT
    deallocate existing clusters. The file will still report its full disk
    usage. This function only sets the attribute; it cannot retroactively
    make a dense file sparse in terms of disk usage.
    """
    path = os.fspath(path)

    if not is_windows():
        raise WSParseError(
            "the sparse attribute is a Windows file-system concept",
            kind="unsupported",
            path=path,
        )

    # Check if path exists
    if not os.path.exists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)

    # Check if path is a directory (not supported for sparse)
    if os.path.isdir(path):
        raise WSParseError(
            "cannot set sparse attribute on a directory",
            kind="unsupported",
            path=path,
        )

    if not enabled:
        raise WSParseError(
            "clearing the sparse attribute is not implemented yet",
            kind="unsupported",
            path=path,
        )

    handle = None
    try:
        handle = get_handle_for_sparse(path, create=False)

        try:
            set_sparse(handle)
        except OSError as exc:
            raise WSParseError(
                "failed to set sparse attribute: %s" % exc,
                kind="os",
                path=path,
            ) from exc

        return sparse_state(path)

    except OSError as exc:
        if isinstance(exc, WSParseError):
            raise
        err_code = getattr(exc, 'errno', None) or getattr(exc, 'winerror', None)
        if err_code in (50,):  # ERROR_NOT_SUPPORTED
            raise WSParseError(
                "filesystem does not support sparse files",
                kind="unsupported",
                path=path,
            ) from exc
        raise WSParseError(str(exc), kind="os", path=path) from exc
    finally:
        if handle is not None:
            close_handle(handle)

